def match(addr, val, length):
    if length == 0:
        return True
    sh = 128 - length
    return (addr >> sh) == (val >> sh)


def handle_lookup(req):
    if set(req.keys()) != {'op', 'image', 'addresses'}:
        raise Invalid()
    if req['op'] != 'lookup':
        raise Invalid()
    image = req['image']
    addresses = req['addresses']
    fib, cuts, caps, S, ms = validate_lookup_image(image)
    if not isinstance(addresses, list):
        raise Invalid()
    if len(addresses) > 20000:
        raise Invalid()
    parsed_addrs = []
    for a in addresses:
        if not isinstance(a, str):
            raise Invalid()
        if '/' in a:
            raise Invalid()
        parsed_addrs.append(parse_ipv6(a))

    # Longest-prefix matching over all image rules (== traversal semantics for
    # a valid image).  Bucket rules by length; at a given length keys are
    # distinct network prefixes, so a direct key lookup is exact.
    by_len = {}
    for (v, l, h) in fib:
        d = by_len.get(l)
        if d is None:
            d = {}
            by_len[l] = d
        key = 0 if l == 0 else (v >> (128 - l))
        d[key] = h
    lengths = sorted(by_len.keys(), reverse=True)

    answers = []
    for a in parsed_addrs:
        hop = None
        pl = None
        for l in lengths:
            if l == 0:
                key = 0
            else:
                key = a >> (128 - l)
            d = by_len[l]
            if key in d:
                hop = d[key]
                pl = l
                break
        answers.append({"hop": hop, "prefix_length": pl})
    return {"status": "ok", "answers": answers}


